"use client";

import { useEffect, useState } from "react";

export function OpeningExperience() {
  const [show, setShow] = useState(() => {
    if (typeof window === "undefined") return false;
    return !localStorage.getItem("archive-opening-seen");
  });

  useEffect(() => {
    if (show) {
      localStorage.setItem("archive-opening-seen", "1");
    }
  }, [show]);

  if (!show) return null;

  return (
    <div className="inscribed-frame mx-auto reading-column bg-deep/85 px-8 py-8" onClick={() => setShow(false)}>
      <p className="font-display text-xl tracking-[0.07em] text-gold">You have entered the Celestial Archive.</p>
      <p className="mt-4 leading-[1.9] text-gold-pale">
        This is a structured exploration of one of the most complex and least understood systems in the Western esoteric tradition - the Enochian system recorded by John Dee and Edward Kelley.
      </p>
      <p className="mt-4 leading-[1.9] text-gold-pale">
        Some material is documented history. Some is tradition-level interpretation. Some remains unresolved. The Archive marks the difference and leaves room for discernment.
      </p>
    </div>
  );
}

